const projects=[{"title":"Cozinha planejada","category":"Cozinhas","photo":"assets/cozinha-planejada.png","desc":"Armários aéreos, gaveteiros e módulos para eletrodomésticos em uma composição sob medida."},{"title":"Closet e guarda-roupa","category":"Closets e armários","photo":"assets/closet-planejado.png","desc":"Cabideiros, sapateiras, nichos e gavetas para organizar o interior do armário."},{"title":"Painel de TV e rack","category":"Painéis e racks","photo":"assets/painel-planejado.png","desc":"Painel amadeirado, rack suspenso e prateleiras integradas na mesma marcenaria."},{"title":"Home office planejado","category":"Home office","photo":"assets/escritorio-planejado.png","desc":"Bancada de trabalho integrada a gaveteiros, armários e estantes sob medida."}];const gallery=document.querySelector('#gallery');function render(filter='Todos'){gallery.replaceChildren();projects.filter(p=>filter==='Todos'||p.category===filter).forEach(p=>{const b=document.createElement('button');b.className='project';b.setAttribute('aria-label','Ver conceito de móvel planejado: '+p.title);b.innerHTML='<div class="photo"><img loading="lazy" src="'+p.photo+'" alt="Móveis planejados: '+p.category.toLowerCase()+'"><span class="arrow" aria-hidden="true">↗</span></div><div class="projectmeta"><h3>'+p.title+'</h3><span>'+p.category+'</span></div><p>'+p.desc+'</p>';b.onclick=()=>{document.querySelector('#fullimage').src=b.querySelector('img').src;document.querySelector('#fullimage').alt=b.querySelector('img').alt;document.querySelector('#fulltitle').textContent=p.title;document.querySelector('#fulldesc').textContent=p.desc+' Conceito ilustrativo gerado com IA; não é um projeto executado pela Alex Ferreira.';document.querySelector('#viewer').showModal()};gallery.append(b)})}render();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b))});render(b.dataset.filter)});const viewer=document.querySelector('#viewer');document.querySelector('#close').onclick=()=>viewer.close();document.querySelector('#inspire').onclick=()=>viewer.close();viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close()}});document.querySelector('#brief').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const summary='MEU PROJETO — ALEX FERREIRA\n\nNome: '+d.get('name')+'\nAmbiente: '+d.get('room')+'\nIdeia: '+d.get('idea');const result=document.querySelector('#result');result.replaceChildren();const message=document.createElement('p');message.textContent='Seu resumo está pronto. Salve e compartilhe com a Alex Ferreira pelo seu canal de contato.';const a=document.createElement('a');a.textContent='Baixar resumo do projeto ↓';a.className='textlink';const url=URL.createObjectURL(new Blob([summary],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='meu-projeto-alex-ferreira.txt';result.append(message,a);a.onclick=()=>setTimeout(()=>URL.revokeObjectURL(url),60000)};